import json, os

path = os.path.join("data", "misconceptions.json")
with open(path, "r", encoding="utf-8") as f:
    data = json.load(f)

existing = {e["id"]: e for e in data["misconceptions"]}

new_entries = [
    # g5-fractions-add
    {"id":"added_tops_and_bottoms","topic_ids":["g5-fractions-add"],"kid_label":"You added the tops and the bottoms","diagnosis":"You added both the numerators and the denominators separately instead of finding a common denominator.","why_it_fails":"Denominators tell you the size of each piece; you can only add numerators when the pieces are the same size.","mini_example":"1/4 + 1/8 -> (1+1)/(4+8) = 2/12 (wrong)","applies_when":"operation_is_fraction_add"},
    {"id":"renamed_bottom_kept_tops","topic_ids":["g5-fractions-add"],"kid_label":"You found a common bottom but forgot to change the tops","diagnosis":"You correctly found the common denominator but did not scale the numerators to match.","why_it_fails":"When you change the denominator, you must multiply the numerator by the same factor to keep the fraction equal.","mini_example":"1/4 + 1/8 -> 2/8 (forgot to convert 1/4 to 2/8)","applies_when":"b != d"},
    {"id":"multiplied_instead_of_adding","topic_ids":["g5-fractions-add"],"kid_label":"You multiplied the fractions instead of adding","diagnosis":"You multiplied numerator by numerator and denominator by denominator like it was a multiplication problem.","why_it_fails":"Adding fractions requires a common denominator; multiplication is a completely different operation.","mini_example":"1/4 + 1/8 -> 1/32 (wrong)","applies_when":"operation_is_fraction_add"},
    {"id":"subtracted_instead_of_adding","topic_ids":["g5-fractions-add"],"kid_label":"You subtracted instead of adding","diagnosis":"You found the difference between the two fractions instead of their sum.","why_it_fails":"Adding means combining amounts; subtracting means finding the gap between them.","mini_example":"1/4 + 1/8 -> 1/4 - 1/8 = 1/8 (wrong)","applies_when":"abs(a/b - c/d) > 0"},
    {"id":"added_tops_kept_first_bottom","topic_ids":["g5-fractions-add"],"kid_label":"You added the tops but kept just one bottom","diagnosis":"You added the numerators but used only the first denominator without finding a common denominator.","why_it_fails":"You need a common denominator before adding numerators; just keeping one denominator does not work.","mini_example":"1/4 + 1/8 -> 2/4 (wrong)","applies_when":"b != d"},
    # g5-volume
    {"id":"added_the_sides","topic_ids":["g5-volume"],"kid_label":"You added all three sides instead of multiplying","diagnosis":"You found the total of length, width, and height by adding instead of multiplying.","why_it_fails":"Volume measures 3D space by multiplying all three dimensions together, not adding them.","mini_example":"6x6x4 -> 6+6+4 = 16 (wrong); correct is 144","applies_when":"operation_is_volume"},
    {"id":"found_base_area_only","topic_ids":["g5-volume"],"kid_label":"You only found the base area","diagnosis":"You multiplied length times width and stopped, forgetting to multiply by height.","why_it_fails":"The base area only covers one layer; you need to multiply by height to count all layers.","mini_example":"6x6x4 -> 6x6 = 36 (wrong); correct is 144","applies_when":"operation_is_volume"},
    {"id":"used_surface_area_formula","topic_ids":["g5-volume"],"kid_label":"You calculated surface area instead of volume","diagnosis":"You found the total area of all six faces instead of the space inside the box.","why_it_fails":"Surface area measures the outside wrapping; volume measures the space inside the shape.","mini_example":"6x6x4 -> 2*(36+24+24) = 168 (wrong); correct is 144","applies_when":"operation_is_volume"},
    {"id":"multiplied_two_sides_then_added_height","topic_ids":["g5-volume"],"kid_label":"You multiplied two sides then just added the height","diagnosis":"You multiplied length and width correctly but then added height instead of multiplying by it.","why_it_fails":"Height must be multiplied because it represents how many base-layers tall the shape is.","mini_example":"6x6x4 -> 6x6+4 = 40 (wrong); correct is 144","applies_when":"operation_is_volume"},
    {"id":"cubed_one_side","topic_ids":["g5-volume"],"kid_label":"You cubed just one side","diagnosis":"You raised one side length to the power of 3 as if it were a perfect cube.","why_it_fails":"Only a perfect cube has all equal sides; a rectangular prism needs all three different dimensions.","mini_example":"6x6x4 -> 6^3 = 216 (wrong); correct is 144","applies_when":"not all sides equal"},
    # g6-percents
    {"id":"multiplied_by_percent_number","topic_ids":["g6-percents"],"kid_label":"You multiplied by the percent number directly","diagnosis":"You multiplied the total by the percent number instead of converting it to a decimal first.","why_it_fails":"Percent means per hundred; you must divide the percent by 100 before multiplying.","mini_example":"15% of 60 -> 15x60 = 900 (wrong); correct is 9","applies_when":"operation_is_percent"},
    {"id":"moved_decimal_wrong_way","topic_ids":["g6-percents"],"kid_label":"You shifted the decimal point the wrong way","diagnosis":"You moved the decimal one place instead of two, treating percent as tenths instead of hundredths.","why_it_fails":"Percent means per 100, so you must move the decimal two places to the left.","mini_example":"15% of 60 -> 1.5x60 = 90 (wrong); correct is 9","applies_when":"operation_is_percent"},
    {"id":"found_the_leftover_amount","topic_ids":["g6-percents"],"kid_label":"You found what was left over, not the percent","diagnosis":"You subtracted the percent amount from the total instead of reporting the percent itself.","why_it_fails":"The question asks for the percent of the total, not the remainder after removing that part.","mini_example":"15% of 60 -> 60-9 = 51 (wrong); correct is 9","applies_when":"operation_is_percent"},
    {"id":"divided_instead_of_multiplying","topic_ids":["g6-percents"],"kid_label":"You divided instead of multiplying","diagnosis":"You divided the total by the percent number rather than multiplying by the decimal.","why_it_fails":"Finding a percent of a number requires multiplication, not division.","mini_example":"15% of 60 -> 60/15 = 4 (wrong); correct is 9","applies_when":"n/p != (p/100)*n"},
    {"id":"found_one_percent_only","topic_ids":["g6-percents"],"kid_label":"You found 1% instead of the asked percent","diagnosis":"You divided by 100 to get 1% but forgot to multiply by the actual percent value.","why_it_fails":"Dividing by 100 gives just 1%; you then need to multiply by the percent number.","mini_example":"15% of 60 -> 60/100 = 0.6 (wrong); correct is 9","applies_when":"operation_is_percent"},
    # g6-equations form ax_b
    {"id":"subtracted_instead_of_dividing","topic_ids":["g6-equations"],"kid_label":"You subtracted the coefficient instead of dividing","diagnosis":"You subtracted the number in front of x from the other side rather than dividing both sides by it.","why_it_fails":"When a number multiplies x, you must divide both sides by that number to isolate x.","mini_example":"6x=54 -> 54-6=48 (wrong); correct is 54/6=9","applies_when":"form == ax_b"},
    {"id":"multiplied_instead_of_dividing","topic_ids":["g6-equations"],"kid_label":"You multiplied both numbers together","diagnosis":"You multiplied the coefficient by the other side instead of dividing.","why_it_fails":"Multiplication is not the inverse of multiplication; you need division to undo it.","mini_example":"6x=54 -> 6x54=324 (wrong); correct is 54/6=9","applies_when":"form == ax_b"},
    {"id":"divided_the_wrong_way","topic_ids":["g6-equations"],"kid_label":"You divided the wrong way around","diagnosis":"You divided the coefficient by the total instead of dividing the total by the coefficient.","why_it_fails":"x = b/a, not a/b; the number alone goes on top.","mini_example":"6x=54 -> 6/54=1/9 (wrong); correct is 54/6=9","applies_when":"form == ax_b"},
    {"id":"ignored_the_coefficient","topic_ids":["g6-equations"],"kid_label":"You ignored the number in front of x","diagnosis":"You wrote the right-hand side as the answer without dividing by the coefficient.","why_it_fails":"The coefficient multiplies x; to find x you must divide both sides by it.","mini_example":"6x=54 -> x=54 (wrong); correct is x=9","applies_when":"form == ax_b"},
    # g6-equations form xpa_b
    {"id":"added_instead_of_subtracting","topic_ids":["g6-equations"],"kid_label":"You added instead of subtracting","diagnosis":"You added the constant to both sides when you should have subtracted it.","why_it_fails":"To undo addition, you must subtract; adding again makes the result even bigger.","mini_example":"x+5=12 -> x=5+12=17 (wrong); correct is x=7","applies_when":"form == xpa_b"},
    {"id":"subtracted_the_wrong_way","topic_ids":["g6-equations"],"kid_label":"You subtracted but in the wrong order","diagnosis":"You subtracted the larger number from the smaller, giving a negative result.","why_it_fails":"x = b - a, not a - b; the constant is removed from the total.","mini_example":"x+5=12 -> x=5-12=-7 (wrong); correct is x=7","applies_when":"form == xpa_b and a-b != b-a"},
    # g6-equations form axpb_c
    {"id":"undid_multiplication_first","topic_ids":["g6-equations"],"kid_label":"You divided before subtracting the constant","diagnosis":"You divided by the coefficient before removing the constant term.","why_it_fails":"Order of operations in reverse: subtract the constant first, then divide by the coefficient.","mini_example":"2x+3=11 -> 11/2-3=2.5 (wrong); correct is (11-3)/2=4","applies_when":"form == axpb_c"},
    {"id":"added_the_constant","topic_ids":["g6-equations"],"kid_label":"You added the constant instead of subtracting it","diagnosis":"You added the constant to the right side before dividing instead of subtracting it.","why_it_fails":"The constant is added to the x-term; to isolate x you must subtract it first.","mini_example":"2x+3=11 -> (11+3)/2=7 (wrong); correct is (11-3)/2=4","applies_when":"form == axpb_c"},
    {"id":"ignored_the_constant_term","topic_ids":["g6-equations"],"kid_label":"You ignored the extra number added to x","diagnosis":"You divided the right side by the coefficient but forgot about the constant added to x.","why_it_fails":"You must subtract the constant from both sides before you can divide.","mini_example":"2x+3=11 -> 11/2=5.5 (wrong); correct is (11-3)/2=4","applies_when":"form == axpb_c"},
    # g5-divide
    {"id":"dropped_the_remainder","topic_ids":["g5-divide"],"kid_label":"You forgot the remainder","diagnosis":"You found the quotient but wrote 0 as the remainder instead of the real leftover.","why_it_fails":"The remainder is the amount left over after dividing evenly; it is rarely zero.","mini_example":"451/16 -> 28 R 0 (wrong); correct is 28 R 3","applies_when":"operation_is_divide"},
    {"id":"swapped_quotient_and_remainder","topic_ids":["g5-divide"],"kid_label":"You swapped the quotient and the remainder","diagnosis":"You wrote the remainder number first and the quotient number second.","why_it_fails":"The quotient is the whole-number result and always comes first in R notation.","mini_example":"451/16 -> 3 R 28 (wrong); correct is 28 R 3","applies_when":"operation_is_divide"},
    {"id":"stopped_subtracting_too_early","topic_ids":["g5-divide"],"kid_label":"You stopped dividing one step too early","diagnosis":"Your quotient is one less than correct because you stopped the long division a step early.","why_it_fails":"You can still subtract the divisor one more time; the remainder should be less than the divisor.","mini_example":"451/16 -> 27 R 19 (wrong); correct is 28 R 3","applies_when":"q >= 1"},
    {"id":"misplaced_quotient_digit","topic_ids":["g5-divide"],"kid_label":"You wrote the quotient in the wrong place","diagnosis":"You multiplied the quotient by 10, placing it in the wrong column.","why_it_fails":"Each digit of the quotient belongs in a specific place-value column.","mini_example":"451/16 -> 280 R 3 (wrong); correct is 28 R 3","applies_when":"operation_is_divide"},
    {"id":"rounded_quotient_up_kept_remainder","topic_ids":["g5-divide"],"kid_label":"You rounded the quotient up","diagnosis":"You rounded the quotient to the next whole number but kept the original remainder.","why_it_fails":"Rounding up the quotient changes the subtraction and therefore changes the remainder too.","mini_example":"451/16 -> 29 R 3 (wrong); correct is 28 R 3","applies_when":"operation_is_divide"},
]

# merge: keep existing entries for non-pilot topics, replace/add pilot entries
pilot_ids = {e["id"] for e in new_entries}
merged = [e for e in data["misconceptions"] if e["id"] not in pilot_ids]
merged.extend(new_entries)
data["misconceptions"] = merged

with open(path, "w", encoding="utf-8") as f:
    json.dump(data, f, indent=2, ensure_ascii=False)
print(f"misconceptions.json written: {len(merged)} entries total")
